edits.newText:
test('allows Count values from 0 through 3 inclusive', () => {
  assert.equal(permit(0), true);
  assert.equal(permit(3), true);
});

test('rejects values outside the inclusive upper and lower bounds', () => {
  assert.equal(permit(-1), false);
  assert.equal(permit(4), false);
});

test('rejects malformed inputs without coercion', () => {
  assert.equal(permit('3'), false);
  assert.equal(permit(null), false);
  assert.equal(permit(undefined), false);
  assert.equal(permit(NaN), false);
  assert.equal(permit(Infinity), false);
  assert.equal(permit(-Infinity), false);
  assert.equal(permit(2.5), false);
});

